/** Combine condition heat with condition-specific and global resistance reductions. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    getResistanceLevel
 * depends    src/mechanics/enemies/types, src/mechanics/workshop/lab-workshop-constants
 * used by    src/calculators/specs.generated, src/mechanics/enemies/index, src/mechanics/waves/resolve-wave-spawn-yield
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { LAB_WORKSHOP_SCALE } from '../workshop/lab-workshop-constants'
import type { GetResistanceLevelInput } from './types'

const F32 = Math.fround

/** resistance level return (f32). */
export function getResistanceLevel(input: GetResistanceLevelInput): number {
  const heat = Math.max(0, Math.floor(input.heatLevel))
  const perBc = F32(input.conditionResistanceReduction)
  const globalReduction = F32(input.globalResistanceReduction)
  const inner = F32(F32(1 - perBc) - globalReduction)
  const scaled = F32(F32(heat) * F32(LAB_WORKSHOP_SCALE) * inner)
  return F32(1 + scaled)
}
